Method.Source:
/// <summary>
/// copies dimension from warehouse proifit centre
/// </summary>
/// <param name = "_inventDim">InventDim record</param>
public void metCopyDimensionfromWarehosue(InventDim _inventDim = this.inventDim())
{
    DimensionDefault            dimensionWarehouse;
    //Copy dimension from Warehouse if exists
    if (_inventDim.InventLocationId)
    {
        dimensionWarehouse = InventLocation::changeDimension(this.DefaultDimension, _inventDim.InventLocationId);
    }
    DimensionDisplayValue dimensionValue = METHelper::getDimensionValue(dimensionWarehouse, METConstants::profitCentre);
    if(dimensionValue)
    {
        this.DefaultDimension = dimensionWarehouse;
    }
    else
    {
        this.DefaultDimension = InventSite::changeDimension(this.DefaultDimension, _inventDim.InventSiteId);
    }
}

    /// <summary>
    /// Copy profit centre from warehouse
    /// </summary>
    /// <param name = "_inventJournalTable">InventJournalTable buffer.</param>
    /// <param name = "_toInventDim">InventDim record</param>
    /// <returns>DimensionDefault</returns>
    public DimensionDefault toDimensionDefault(
                                                InventJournalTable  _inventJournalTable,
                                                InventDim           _toInventDim)
    {
        DimensionDefault   metToDimension;
        metToDimension = next toDimensionDefault(_inventJournalTable, _toInventDim);

        if (this.JournalType != InventJournalType::Transfer)
        {
            return metToDimension;
        }
        metToDimension = InventLocation::changeDimension(this.DefaultDimension, _toInventDim.InventLocationId);

        DimensionDisplayValue dimensionValue = METHelper::getDimensionValue(metToDimension, METConstants::profitCentre);
        if(dimensionValue)
        {
            metToDimension = metToDimension;
        }
        else
        {
            metToDimension = InventSite::changeDimension(this.DefaultDimension, _toInventDim.InventSiteId);
        }

        return metToDimension;
    }

